import{j as l,w as b,t as e,J as t,bB as s,I as n,be as i,H as d,aT as o,aG as f}from"./index-CvIcJb--.js";const r="https://visualizer.matthiasheckel.com/assets/textumfluss-screenshot-DZYiecOM.png",c={class:"lesson-page"},u={class:"shell"},h=d('<header data-v-fbb92a02><p class="eyebrow" data-v-fbb92a02>ADOBE INDESIGN · MINI TUTORIAL</p><h1 data-v-fbb92a02>Text um einen Kreis fließen lassen</h1><p class="goal" data-v-fbb92a02>Du lässt einen Text automatisch um einen Kreis laufen.</p></header><p class="intro" data-v-fbb92a02>Probiere den Textumfluss an einer Kopie deines Café-Flyers aus. Die Form verdrängt den Text. Verschiebst du sie, passt sich der Text an.</p><section aria-labelledby="terms-title" data-v-fbb92a02><h2 id="terms-title" data-v-fbb92a02>Einfach erklärt</h2><dl data-v-fbb92a02><div data-v-fbb92a02><dt data-v-fbb92a02>Textumfluss</dt><dd data-v-fbb92a02>Eine Einstellung am Objekt, um das der Text herumfließen soll.</dd></div><div data-v-fbb92a02><dt data-v-fbb92a02>Abstand</dt><dd data-v-fbb92a02>Freier Platz zwischen Form und Text für bessere Lesbarkeit.</dd></div></dl></section>',3),m={class:"document-image"},g=["href"],v=["src"],x=d('<section class="practice" aria-labelledby="practice-title" data-v-fbb92a02><h2 id="practice-title" data-v-fbb92a02>So gehst du vor</h2><ol data-v-fbb92a02><li data-v-fbb92a02>Öffne deinen Flyer und speichere eine Kopie als <strong data-v-fbb92a02>„Textumfluss.indd“</strong> in deinem Namensordner.</li><li data-v-fbb92a02>Verwende einen ausreichend großen Textrahmen mit mehreren Zeilen, zum Beispiel mit deinem Café-Fließtext.</li><li data-v-fbb92a02>Zeichne mit dem <strong data-v-fbb92a02>Ellipsenwerkzeug (L)</strong> einen Kreis über einen Teil des Textes. Halte beim Aufziehen die Umschalttaste gedrückt, damit ein gleichmäßiger Kreis entsteht.</li><li data-v-fbb92a02>Wähle den Kreis mit dem schwarzen Auswahlpfeil aus. Öffne <strong data-v-fbb92a02>Fenster → Textumfluss</strong>.</li><li data-v-fbb92a02>Aktiviere <strong data-v-fbb92a02>„Umfließen der Objektform“</strong> (drittes Symbol). Der Text folgt nun der runden Kontur. „Umfließen des Begrenzungsrahmens“ (zweites Symbol) würde dagegen einen rechteckigen Bereich freihalten.</li><li data-v-fbb92a02>Stelle im Textumfluss-Bedienfeld bei <strong data-v-fbb92a02>Versatz</strong> zunächst <strong data-v-fbb92a02>3 mm</strong> ein. Je nach Bedienfeldansicht musst du dieses zunächst vergrößern oder über das Bedienfeldmenü <strong data-v-fbb92a02>„Optionen anzeigen“</strong> aufrufen. Beim Umfließen der Objektform wird der Abstand zur Kreiskontur über das Versatzfeld eingestellt, nicht über vier einzelne Abstandsfelder. Achte darauf, dass der Kreis ausgewählt ist.</li><li data-v-fbb92a02><strong data-v-fbb92a02>Andere Textrahmen vom Textumfluss ausnehmen:</strong> Der Kreis beeinflusst zunächst auch andere Textrahmen in seinem Bereich. Wähle einen Textrahmen aus, der nicht reagieren soll. Öffne <strong data-v-fbb92a02>Objekt → Textrahmenoptionen (⌘ + B)</strong> und aktiviere <strong data-v-fbb92a02>„Textumfluss ignorieren“</strong>. Wiederhole das bei Bedarf für weitere Textrahmen.</li><li data-v-fbb92a02>Verschiebe den Kreis und beobachte, wie sich der Fließtext verändert. Lass genügend Platz für gut lesbare Zeilen. Vergrößere bei Textüberlauf den Textrahmen.</li><li data-v-fbb92a02>Prüfe über <strong data-v-fbb92a02>Ansicht → Bildschirmmodus → Vorschau</strong> das Ergebnis. Speichere <strong data-v-fbb92a02>„Textumfluss.indd“</strong>.</li></ol></section><section class="check" aria-labelledby="check-title" data-v-fbb92a02><h2 id="check-title" data-v-fbb92a02>Prüfe dein Ergebnis</h2><p data-v-fbb92a02>Der Text läuft um den Kreis, hat genügend Abstand und bleibt vollständig sichtbar.</p></section><section class="practice" aria-labelledby="help-title" data-v-fbb92a02><h2 id="help-title" data-v-fbb92a02>Der Text fließt noch nicht um die Form?</h2><ul data-v-fbb92a02><li data-v-fbb92a02>Wähle die Form aus, wenn du den Textumfluss einstellst.</li><li data-v-fbb92a02>Prüfe die Ebenen: Lege die Form für diese Übung über den Text.</li><li data-v-fbb92a02>Wähle den Textrahmen und öffne <strong data-v-fbb92a02>Objekt → Textrahmenoptionen</strong>. „Textumfluss ignorieren“ muss ausgeschaltet sein.</li></ul></section><p class="source" data-v-fbb92a02><a href="https://www.adobe.com/de/learn/indesign/web/wrap-text-layout" target="_blank" rel="noopener noreferrer" data-v-fbb92a02>Bei Adobe nachlesen: Textumfluss ↗</a></p>',4),T={class:"pager","aria-label":"Tutorialnavigation"},p={__name:"TextumflussTutorial",setup(_){return(k,w)=>{const a=o("RouterLink");return f(),b("main",c,[e("div",u,[t(a,{to:"/medientechnik/adobe-indesign/mini-tutorials",class:"back"},{default:s(()=>[n("← Mini Tutorials")]),_:1}),h,e("figure",m,[e("a",{href:i(r),target:"_blank",rel:"noopener noreferrer","aria-label":"Screenshot zum Textumfluss vergrößern (neuer Tab)"},[e("img",{src:i(r),width:"3622",height:"2072",alt:"Café-Florale-Flyer in Adobe InDesign: Der Fließtext läuft um einen runden Bereich. Rechts ist das Textumfluss-Bedienfeld geöffnet."},null,8,v)],8,g)]),x,e("nav",T,[t(a,{to:"/medientechnik/adobe-indesign/mini-tutorials"},{default:s(()=>[n("← Zur Übersicht")]),_:1})])])])}}},B=l(p,[["__scopeId","data-v-fbb92a02"]]);export{B as default};
